-- Seed section hover tooltips (run once; Worker updates these after content changes).
INSERT OR REPLACE INTO site_config (key, value) VALUES (
  'section_hints',
  '{"Thinking":"Short notes and media—photos, videos, voice memos, Spotify tracks, and YouTube clips—posted often without essay polish. Browse chronologically or as a grid, and filter by type. Recent threads run through NYC, travel, books, politics, sports, and whatever caught my eye that day: loose, opinionated, sometimes funny, always in the moment.","Writing":"Longer pieces when I have something to say—a mix of personal essays, small experiments, and the occasional haiku. Topics wander from style and walking to film, routine, building this site, and what it means to pay attention. Less of a diary, more room to think out loud.","Reading":"A storefront-style log of books I''m reading—cover art, title, and author, linked to Bookshop.org and grouped by month. Mostly literary fiction and translated work, not bestseller churn. List or grid view; a snapshot of what''s open on my desk, not reviews or ratings.","Sharing":"A linklog of URLs that caught my eye—title and link only, newest first. You''ll find art and design, literature, architecture, NYC politics, sports, history, film, and the occasional rabbit hole. Not a news feed or hot-take column—more a personal signal of what I''m reading and think is worth a click."}'
);
